import{_ as e,o as a,c as i,ao as r}from"./chunks/framework.CDuh1GR-.js";const s="/BVDOutbreakSize/previews/PR884/assets/rt.DydbTN-_.png",n="/BVDOutbreakSize/previews/PR884/assets/province-47.DFCVxmN2.png",o="/BVDOutbreakSize/previews/PR884/assets/infections.BnvOyKZ_.png",u=JSON.parse('{"title":"Summary dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"estimates/summary.md","filePath":"estimates/summary.md","lastUpdated":null}'),d={name:"estimates/summary.md"};function l(h,t,g,c,m,p){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="Summary-dashboard" tabindex="-1">Summary dashboard <a class="header-anchor" href="#Summary-dashboard" aria-label="Permalink to &quot;Summary dashboard {#Summary-dashboard}&quot;">​</a></h1><p><strong>Last updated:</strong> 24 September 2026.</p><p><strong>Data as of:</strong> 22 September 2026.</p><p>An outbreak of Ebola disease caused by Bundibugyo virus (BVD) is ongoing in the Democratic Republic of the Congo (DRC), with cases also detected across the border in Uganda. This is a real-time joint Bayesian estimate of the current size of that outbreak, refreshed as new data arrive. Most infections are not yet reported, so the current size has to be inferred from the surveillance data that are available. The model is a discrete-time renewal process on a daily grid. It fits in a single posterior the daily counts the INSP situation reports publish, including the suspected and confirmed case and death series as well as the laboratory, isolation, treatment-centre and recovery records. We also digitise the epidemic curve by symptom-onset date as intermittently reported in the INSP situation reports and fit them using a model that accounts for time-varying ascertainment and reporting delays. Finally, we fit to data on initial exports of cases and deaths to Uganda, taken from the WHO situation reports and Disease Outbreak News. The same infection process generates all of them, staged to daily symptom onsets and routed into every observation stream. A genetic bound on the time to the most recent common ancestor and priors from the McCabe et al. report complete the inputs. From these it estimates the infections and deaths to date, reported and unreported, the time-varying reproduction number with its growth rate and doubling time, the case-fatality ratio, and the ascertainment of each surveillance system. Every release projects each DRC stream a week ahead. The forecasts are scored with the continuous ranked probability score against the data that arrive later and against a persistence baseline. The aim is a transparent estimate of how far the outbreak has already grown, and of how much each published stream contributes to it.</p><p>This page summarises the headline results. See the <a href="./national">National</a> and <a href="./province">Provinces</a> pages for the estimates at each level. See <a href="./../forecasts/national">Forecasts</a> for the week ahead. See the <a href="./../evaluation/insample/national">in-sample checks</a> for how the model fits the data and the <a href="./../evaluation/forecast/national">forecast evaluation</a> for how past forecasts scored, each with a province page alongside. See <a href="./../methods">Methods</a> for the model, <a href="./../limitations">Limitations</a> for its caveats and <a href="./../sensitivity">Sensitivity</a> for the sensitivity analyses.</p><h2 id="Headline-estimates" tabindex="-1">Headline estimates <a class="header-anchor" href="#Headline-estimates" aria-label="Permalink to &quot;Headline estimates {#Headline-estimates}&quot;">​</a></h2><ul><li><p><strong>Cumulative infections:</strong> the outbreak is estimated to have caused 30% 16243–19655, 60% 14405–22020, 90% 12016–26779 infections to date, reported and unreported.</p></li><li><p>Against the 7820 laboratory-confirmed cases by the cut-off that is roughly 1.5–3.4× as many infections, so confirmed cases are estimated to capture only a small share of the outbreak.</p></li><li><p><strong>Outbreak start and age:</strong> the outbreak is estimated to have begun on a start date of 30% 2026-03-18–2026-03-22, 60% 2026-03-16–2026-03-24, 90% 2026-03-10–2026-03-26, an elapsed age to the cut-off of 30% 184–188, 60% 182–190, 90% 180–196 days.</p></li><li><p><strong>Growth rate and doubling time:</strong> the initial growth rate is estimated to have been 30% 0.05–0.064, 60% 0.043–0.074, 90% 0.032–0.094 per day, an initial doubling time of 30% 13.9–10.8, 60% 16.2–9.3, 90% 21.6–7.4 days. The latest growth rate is estimated to be 30% -0.017–0.007, 60% -0.035–0.024, 90% -0.073–0.066 per day, a latest doubling time of 30% -41.1–95.2, 60% -19.7–29.1, 90% -9.5–10.6 days.</p></li><li><p><strong>Reproduction number:</strong> the initial reproduction number is estimated to have been 30% 1.19–1.26, 60% 1.16–1.32, 90% 1.12–1.46 and the latest to be 30% 0.94–1.03, 60% 0.86–1.1, 90% 0.72–1.27.</p></li><li><p><strong>Case-fatality ratio:</strong> the case-fatality ratio is estimated to be 30% 0.44–0.5, 60% 0.41–0.53, 90% 0.36–0.59.</p></li><li><p><strong>Shift from priors:</strong> how far the data has moved each estimate from its prior, in prior interquartile ranges, where a value of one means the posterior median sits one prior interquartile range from the prior median, zero means unchanged, and the sign gives the direction. The fit moves the cumulative infection count by -0.01, the outbreak age by -1.01 and the doubling time by -1.15; the largest move is in the doubling time.</p></li></ul><h3 id="Outbreak-size-and-timing" tabindex="-1">Outbreak size and timing <a class="header-anchor" href="#Outbreak-size-and-timing" aria-label="Permalink to &quot;Outbreak size and timing {#Outbreak-size-and-timing}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Quantity</th><th style="text-align:right;">Lower 90%</th><th style="text-align:right;">Lower 60%</th><th style="text-align:right;">Lower 30%</th><th style="text-align:right;">Upper 30%</th><th style="text-align:right;">Upper 60%</th><th style="text-align:right;">Upper 90%</th></tr></thead><tbody><tr><td style="text-align:right;">Cumulative infections</td><td style="text-align:right;">12016</td><td style="text-align:right;">14405</td><td style="text-align:right;">16243</td><td style="text-align:right;">19655</td><td style="text-align:right;">22020</td><td style="text-align:right;">26779</td></tr><tr><td style="text-align:right;">Outbreak age (days)</td><td style="text-align:right;">180</td><td style="text-align:right;">182</td><td style="text-align:right;">184</td><td style="text-align:right;">188</td><td style="text-align:right;">190</td><td style="text-align:right;">196</td></tr></tbody></table><h3 id="Growth-and-severity" tabindex="-1">Growth and severity <a class="header-anchor" href="#Growth-and-severity" aria-label="Permalink to &quot;Growth and severity {#Growth-and-severity}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Quantity</th><th style="text-align:right;">Lower 90%</th><th style="text-align:right;">Lower 60%</th><th style="text-align:right;">Lower 30%</th><th style="text-align:right;">Upper 30%</th><th style="text-align:right;">Upper 60%</th><th style="text-align:right;">Upper 90%</th></tr></thead><tbody><tr><td style="text-align:right;">Initial reproduction number</td><td style="text-align:right;">1.12</td><td style="text-align:right;">1.16</td><td style="text-align:right;">1.19</td><td style="text-align:right;">1.26</td><td style="text-align:right;">1.32</td><td style="text-align:right;">1.46</td></tr><tr><td style="text-align:right;">Latest reproduction number</td><td style="text-align:right;">0.72</td><td style="text-align:right;">0.86</td><td style="text-align:right;">0.94</td><td style="text-align:right;">1.03</td><td style="text-align:right;">1.1</td><td style="text-align:right;">1.27</td></tr><tr><td style="text-align:right;">Latest growth rate (per day)</td><td style="text-align:right;">-0.07</td><td style="text-align:right;">-0.04</td><td style="text-align:right;">-0.02</td><td style="text-align:right;">0.01</td><td style="text-align:right;">0.02</td><td style="text-align:right;">0.07</td></tr><tr><td style="text-align:right;">Latest doubling time (days)</td><td style="text-align:right;">-9.53</td><td style="text-align:right;">-19.69</td><td style="text-align:right;">-41.1</td><td style="text-align:right;">95.17</td><td style="text-align:right;">29.05</td><td style="text-align:right;">10.55</td></tr><tr><td style="text-align:right;">Case-fatality ratio</td><td style="text-align:right;">0.36</td><td style="text-align:right;">0.41</td><td style="text-align:right;">0.44</td><td style="text-align:right;">0.5</td><td style="text-align:right;">0.53</td><td style="text-align:right;">0.59</td></tr></tbody></table><p>All intervals are equal-tailed 30%, 60% and 90% credible intervals from the joint posterior.</p><h3 id="By-province" tabindex="-1">By province <a class="header-anchor" href="#By-province" aria-label="Permalink to &quot;By province {#By-province}&quot;">​</a></h3><p>The model runs one renewal equation per province and fits the national streams against the summed provinces, so the national count above is the sum of the provinces. Each range is an equal-tailed 90% credible interval. The reproduction number and the relative ascertainment are read together, because the per-province case data identify only their product. Each province&#39;s own estimates are in the <a href="/BVDOutbreakSize/previews/PR884/estimates/province#Detail-by-province">detail by province</a>. Modelled infections by province, the per-province parameter detail and the composition checks are on the same page.</p><ul><li><p><strong>Share of infections:</strong> Ituri 62–78%, Nord-Kivu 17–30%, Haut-Uele 3–8% and Other provinces 1–3% of infections to date. Ituri has the most infections with probability over 99%.</p></li><li><p><strong>Reproduction number:</strong> at the cut-off it runs from 0.68–1.25 in Nord-Kivu to 0.74–1.49 in Other provinces. The probability it is above one is 38% in Ituri, 39% in Nord-Kivu, 44% in Haut-Uele and 64% in Other provinces, so 1 of 4 provinces is more likely than not to be growing.</p></li><li><p><strong>Case-fatality ratio:</strong> from 28.4–59.1% in Haut-Uele to 39.2–88.2% in Nord-Kivu.</p></li><li><p><strong>Case ascertainment relative to the national average:</strong> from 0.47–1.32 in Other provinces to 0.85–1.93 in Ituri.</p></li><li><p><strong>Importation:</strong> infections imported from another province make up 0.0–0.4% of infections to date.</p></li></ul><h3 id="Fit-diagnostics" tabindex="-1">Fit diagnostics <a class="header-anchor" href="#Fit-diagnostics" aria-label="Permalink to &quot;Fit diagnostics {#Fit-diagnostics}&quot;">​</a></h3><p>The joint fit fails the convergence checks.</p><details><summary>Expand: how the fits behind these numbers sampled</summary><p>R-hat sets the spread within each chain against the spread across chains, and a value near one says the chains agree. The bulk effective sample size is the number of independent draws the chains are worth, counted for the parameter where that count is lowest. A divergent transition is a step the sampler could not take accurately. The <a href="./../sensitivity">Sensitivity</a> page breaks these numbers down by parameter.</p><p>Its worst R-hat is 1.83 and its lowest bulk effective sample size is 6, with 0 divergent transitions in 2000 draws. A fit passes without warnings when its worst R-hat is at most 1.05, its effective sample sizes are at least 100 and at most 1% of its draws diverge.</p><p>Across all 10 fits the worst R-hat is 1.83, in the joint fit. The lowest bulk effective sample size is 5, in the frozen (1wk back) fit. Only the joint fit is held to the thresholds above.</p><table tabindex="0"><thead><tr><th style="text-align:right;">fit</th><th style="text-align:right;">max_rhat</th><th style="text-align:right;">min_ess_bulk</th><th style="text-align:right;">divergences</th></tr></thead><tbody><tr><td style="text-align:right;">joint</td><td style="text-align:right;">1.831</td><td style="text-align:right;">6</td><td style="text-align:right;">0</td></tr><tr><td style="text-align:right;">joint, no patches</td><td style="text-align:right;">1.058</td><td style="text-align:right;">62</td><td style="text-align:right;">0</td></tr><tr><td style="text-align:right;">exports</td><td style="text-align:right;">1.233</td><td style="text-align:right;">7</td><td style="text-align:right;">27</td></tr><tr><td style="text-align:right;">deaths (DRC)</td><td style="text-align:right;">1.212</td><td style="text-align:right;">7</td><td style="text-align:right;">9</td></tr><tr><td style="text-align:right;">cases (DRC)</td><td style="text-align:right;">1.067</td><td style="text-align:right;">41</td><td style="text-align:right;">1</td></tr><tr><td style="text-align:right;">confirmed (DRC)</td><td style="text-align:right;">1.043</td><td style="text-align:right;">50</td><td style="text-align:right;">8</td></tr><tr><td style="text-align:right;">confirmed deaths (DRC)</td><td style="text-align:right;">1.065</td><td style="text-align:right;">31</td><td style="text-align:right;">0</td></tr><tr><td style="text-align:right;">isolation (DRC)</td><td style="text-align:right;">1.064</td><td style="text-align:right;">39</td><td style="text-align:right;">0</td></tr><tr><td style="text-align:right;">onsets (DRC)</td><td style="text-align:right;">1.074</td><td style="text-align:right;">24</td><td style="text-align:right;">0</td></tr><tr><td style="text-align:right;">frozen (1wk back)</td><td style="text-align:right;">1.338</td><td style="text-align:right;">5</td><td style="text-align:right;">1</td></tr></tbody></table></details><h2 id="Estimated-reproduction-number" tabindex="-1">Estimated reproduction number <a class="header-anchor" href="#Estimated-reproduction-number" aria-label="Permalink to &quot;Estimated reproduction number {#Estimated-reproduction-number}&quot;">​</a></h2><p>The time-varying reproduction number R(t), the average number of further infections caused by each infection. A value above one means the outbreak is growing.</p><p><img src="'+s+'" alt=""></p><p>The same trajectory by province, with the national one in grey behind each panel. A panel tracking grey says that province moves with the national trend.</p><p><img src="'+n+'" alt=""></p><h2 id="Infections-over-time" tabindex="-1">Infections over time <a class="header-anchor" href="#Infections-over-time" aria-label="Permalink to &quot;Infections over time {#Infections-over-time}&quot;">​</a></h2><p>Modelled cumulative infections, symptom onsets and deaths. These are the underlying outbreak, upstream of the testing and reporting that produce the observed counts, so they are larger than the reported cases.</p><p><img src="'+o+'" alt=""></p><h2 id="Estimate-variation-by-data-stream" tabindex="-1">Estimate variation by data stream <a class="header-anchor" href="#Estimate-variation-by-data-stream" aria-label="Permalink to &quot;Estimate variation by data stream {#Estimate-variation-by-data-stream}&quot;">​</a></h2><p>The <a href="/BVDOutbreakSize/previews/PR884/sensitivity#Outbreak-size-estimated-by-each-data-stream">outbreak size</a> and the <a href="/BVDOutbreakSize/previews/PR884/sensitivity#Reproduction-number-estimated-by-each-data-stream">reproduction number</a> each data stream implies on its own are on the sensitivity page.</p><hr><p>For the full results, methods and code see the <a href="./national">National</a> page and the <a href="https://github.com/epiforecasts/BVDOutbreakSize" target="_blank" rel="noreferrer">epiforecasts/BVDOutbreakSize</a> repository.</p>',30)])])}const b=e(d,[["render",l]]);export{u as __pageData,b as default};
